        cst = dist(depot, r[0]) + dist(r[-1], depot)
        for i in range(len(r) - 1):
            cst += dist(r[i], r[i + 1])
        return cst

    # Deterministic sweep order around depot without math imports
    def angle_key(i):
        x, y = coords[i]
        dx = x - dx0
        dy = y - dy0
        quad = 0
        if dx < 0 and dy >= 0:
            quad = 1
        elif dx < 0 and dy < 0:
            quad = 2
        elif dx >= 0 and dy < 0:
            quad = 3
        denom = abs(dx) + abs(dy) + 1e-12
        slope = dy / denom
        return (quad, slope, dist(depot, i), i)

    remaining = set(customers)
    angle_order = sorted(customers, key=angle_key)
    routes = []
    idx = 0

    while remaining:
        seed = None
        while idx < len(angle_order):
            c = angle_order[idx]
            idx += 1
            if c in remaining and demand.get(c, 0.0) <= capacity + 1e-9:
                seed = c
                break
        if seed is None:
            seed = min(remaining, key=lambda c: (demand.get(c, 0.0) > capacity + 1e-9, dist(depot, c), c))
        route = [seed]
        remaining.remove(seed)
        load = demand.get(seed, 0.0)

        while True:
            last = route[-1]
            best = None
            best_key = None
            for c in remaining:
                dc = demand.get(c, 0.0)
                if load + dc > capacity + 1e-9:
                    continue
                key = (dist(last, c), dist(depot, c), dc, c)
                if best is None or key < best_key:
                    best = c
                    best_key = key
            if best is None:
                break
            route.append(best)
            remaining.remove(best)
            load += demand.get(best, 0.0)

        routes.append(route)

    # Relocate improvement
    improved = True
    while improved:
        improved = False
        for i in range(len(routes)):
            if improved:
                break
            ri = routes[i]
            if not ri:
                continue
            for p in range(len(ri)):
                c = ri[p]
                dc = demand.get(c, 0.0)
                base_ri = route_cost(ri)
                new_ri = ri[:p] + ri[p + 1:]
                new_ri_cost = route_cost(new_ri)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_load(rj) + dc > capacity + 1e-9:
                        continue
                    best_pos = None
                    best_delta = None
                    old_rj_cost = route_cost(rj)
                    for pos in range(len(rj) + 1):
                        new_rj = rj[:pos] + [c] + rj[pos:]
                        delta = route_cost(new_rj) - old_rj_cost
                        if best_pos is None or delta < best_delta - 1e-12 or (abs(delta - best_delta) <= 1e-12 and pos < best_pos):
                            best_pos = pos
                            best_delta = delta
                    if best_pos is not None:
                        total_delta = (new_ri_cost - base_ri) + best_delta
                        if total_delta < -1e-9:
                            routes[i] = new_ri
                            routes[j] = rj[:best_pos] + [c] + rj[best_pos:]
                            if not routes[i]:
                                routes.pop(i)
                            improved = True
                            break
                if improved:
                    break

    routes = [r for r in routes if r]

    # 2-opt within routes
    for idx_r in range(len(routes)):
        r = routes[idx_r]
        if len(r) < 4:
            continue
        changed = True
        while changed:
            changed = False
            n = len(r)
            for i in range(n - 3):
                for k in range(i + 2, n - 1):
                    a = depot if i < 0 else r[i]
                    b = r[i + 1]
                    c = r[k]
                    d = depot if k + 1 == n else r[k + 1]
                    if dist(a, c) + dist(b, d) + 1e-12 < dist(a, b) + dist(c, d):
                        r[i + 1:k + 1] = reversed(r[i + 1:k + 1])
                        changed = True
        routes[idx_r] = r

    return routes
